#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/tool_strip_panel/tool_strip_panel_values/tool_strip_panel_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ToolStripPanel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tool_strip_panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The side of the container the panel lines; changing it turns the joined strips to its orientation. An invalid edge throws std::invalid_argument, and an edge that would turn a joined StatusStrip vertical throws std::logic_error; either changes nothing.
template <typename Declaring>
struct ToolStripPanelEdgePropertyCapability {
    PropertyCell<ToolStripPanelEdge, ToolStripPanelEdgePropertyCapability<Declaring>> edge{ToolStripPanelEdge::top};

    static void assign(ToolStripPanelEdgePropertyCapability& capability, ToolStripPanelEdge incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.edge), incoming);
        if (!capability.edge.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.edge));
    }
};

// Every ToolStripPanel capability, in the order the declaring class takes them.
template <typename Declaring>
struct ToolStripPanelCapabilities : public ToolStripPanelEdgePropertyCapability<Declaring> {};

} // namespace gui_forms
